head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > M > getValue]<br/>Secret 컴포넌트의 실제 입력값을 반환합니다.",
    "validation" : [
        "화면에는 입력값이 마스킹되어 표시되지만 getValue() 메소드는 마스킹되지 않은 평문 문자열을 반환합니다.",
        "Secret 컴포넌트에서 값을 입력중일때 getValue() 메소드를 실행하면 입력값의 내부 갱신 시점에 따라 이전 입력값을 반환할 수 있습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트이며 생성 직후 초기값 secret (6자) 이 설정됩니다\n[절차] getValue 클릭 -> target1 에 직접 키보드로 문자를 입력하거나 지우면서 결과창 확인\n[확인] 화면의 마스킹 표시와 getValue 반환값 비교, 키 입력마다 onkeydown / onkeyup 시점의 getValue 반환값 비교"', '', 'label1');

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정)
    await $c.gcm.createBasicSecret('', 'ev:onkeydown="scwin.target1_onkeydown" ev:onkeyup="scwin.target1_onkeyup"');
}



// getValue 반환값 - validation 1 판정 출력 (화면 마스킹 표시와 대비)
scwin.btn_getValue_onclick = function (e) {
    let strValue = target1.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : " + strValue + " (" + typeof strValue + ", " + strValue.length + "자) / 입력창 type : " + target1.render.type);
}



// 입력 반영 전 시점 - validation 2 판정 출력 (누른 키가 아직 반환값에 반영되지 않음)
scwin.target1_onkeydown = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onkeydown (key : " + e.key + ") -> getValue() : " + target1.getValue());
}



// 입력 반영 후 시점 - validation 2 판정 출력 (onkeydown 시점 값과 대비)
scwin.target1_onkeyup = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onkeyup (key : " + e.key + ") -> getValue() : " + target1.getValue());
}
